<?php
namespace Tests;
use App\Services\{SalonStore,GuestPasswords,Notifications,Connections,ReviewRequests,Tenant};
use Carbon\CarbonImmutable as Time;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{DB,Artisan,Hash,Crypt,Mail,Http};
final class GrowthTest extends TestCase{
 private string $path;
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');$this->path=storage_path('framework/growth-'.bin2hex(random_bytes(8)));config(['integrations.path'=>$this->path,'operator.connections_path'=>$this->path.'-platform']);Artisan::call('migrate',['--force'=>true]);foreach(['guest_auth_tokens','guest_credentials','guest_invitations','deliveries','calendar_tasks','calendar_connections','mail_templates','guest_accounts','salon_state','providers'] as $t)DB::table($t)->delete();DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode(SalonStore::initial())]);Http::preventStrayRequests();$this->withSession(['_token'=>str_repeat('g',40)])->withHeader('X-CSRF-TOKEN',str_repeat('g',40));}
 protected function tearDown():void{Time::setTestNow();\Carbon\Carbon::setTestNow();foreach(glob($this->path.'*') as $p)unlink($p);parent::tearDown();}
 private function admin():void{$this->withSession(['admin'=>true,'provider_id'=>1]);}
 private function booking(array $v=[]):array{return array_replace(['name'=>'Vendég','email'=>'guest@example.com','phone'=>'06301234567','staff'=>'anna','services'=>['cut'],'start'=>'2035-03-12T09:00:00Z'],$v);}
 private function signup():string{$this->postJson('/api/guest/auth/register',['email'=>'person@example.com','name'=>'Untrusted Name','password'=>'attacker-known-password'])->assertCreated()->assertJsonPath('verificationRequired',true);$row=DB::table('guest_auth_tokens')->where('purpose','verify')->first();return json_decode(Crypt::decryptString($row->payload),true)['token'];}
 private function verify(string $token):void{$this->postJson('/api/guest/auth/verify',['token'=>$token,'name'=>'Verified Name','phone'=>'+36301112233','password'=>'A-new-secret-password','password_confirmation'=>'A-new-secret-password'])->assertOk()->assertSessionHas('guest_password_version',2);}
 public function test_email_signup_requires_mail_proof_and_fresh_password_not_unverified_supplied_password():void{$token=$this->signup();$this->assertNull(session('guest_id'));$row=DB::table('guest_credentials')->first();$this->assertFalse(Hash::check('attacker-known-password',$row->password_hash));$this->assertStringNotContainsString($token,DB::table('guest_auth_tokens')->first()->token_hash);$this->postJson('/api/guest/auth/login',['email'=>'person@example.com','password'=>'attacker-known-password'])->assertUnauthorized();$this->verify($token);$this->getJson('/api/guest')->assertOk()->assertJsonPath('name','Verified Name')->assertJsonPath('phone','06301112233');$this->assertTrue(Hash::check('A-new-secret-password',DB::table('guest_credentials')->first()->password_hash));$this->postJson('/api/guest/auth/verify',['token'=>$token,'name'=>'Other','password'=>'another-long-password','password_confirmation'=>'another-long-password'])->assertUnprocessable();$this->getJson('/api/platform/providers')->assertUnauthorized();}
 public function test_password_login_and_reset_do_not_grant_provider_rights_and_revoke_old_sessions():void{$this->verify($this->signup());$guest=session('guest_id');$this->withSession(['guest_id'=>null,'guest_password_account'=>null,'guest_password_version'=>null]);$this->postJson('/api/guest/auth/login',['email'=>'PERSON@example.com','password'=>'A-new-secret-password','returnTo'=>'booking'])->assertOk()->assertJsonPath('url','/foglalas?provider=1#public-form');$oldVersion=session('guest_password_version');$this->postJson('/api/guest/auth/forgot',['email'=>'person@example.com'])->assertOk();$row=DB::table('guest_auth_tokens')->where('purpose','reset')->first();$token=json_decode(Crypt::decryptString($row->payload),true)['token'];$this->postJson('/api/guest/auth/reset',['token'=>$token,'password'=>'Reset-secret-password','password_confirmation'=>'Reset-secret-password'])->assertOk();$this->withSession(['guest_id'=>$guest,'guest_password_account'=>$guest,'guest_password_version'=>$oldVersion]);$this->getJson('/api/guest')->assertUnauthorized();$this->postJson('/api/guest/auth/login',['email'=>'person@example.com','password'=>'A-new-secret-password'])->assertUnauthorized();$this->postJson('/api/guest/auth/login',['email'=>'person@example.com','password'=>'Reset-secret-password'])->assertOk();$this->getJson('/api/state')->assertUnauthorized();}
 public function test_verification_email_uses_the_real_queue_with_encrypted_payload_and_central_smtp():void{$token=$this->signup();$this->assertStringNotContainsString('person@example.com',DB::table('guest_auth_tokens')->first()->payload);app(Connections::class)->save(['smtp_host'=>'smtp.example.invalid','smtp_port'=>587,'mail_from'=>'sender@example.com']);Mail::fake();$result=app(Notifications::class)->run();$this->assertSame(1,$result['sent']);Mail::assertSent(\App\Mail\NotificationMail::class,fn($m)=>str_contains($m->contentHtml,urlencode($token))&&$m->hasTo('person@example.com'));}
 public function test_expired_tokens_and_bad_confirmation_never_activate_account():void{$token=$this->signup();DB::table('guest_auth_tokens')->update(['expires_at'=>now()->subMinute()]);$this->postJson('/api/guest/auth/verify',['token'=>$token,'name'=>'Név','password'=>'a-long-enough-password','password_confirmation'=>'a-long-enough-password'])->assertUnprocessable();$this->assertNull(DB::table('guest_credentials')->first()->verified_at);$this->postJson('/api/guest/auth/register',['email'=>'invalid'])->assertUnprocessable();}
 public function test_blacklist_is_tenant_local_matches_normalized_contacts_and_allows_manual_bookings():void{$this->admin();$c=$this->postJson('/api/clients',['name'=>'Vendég','email'=>'guest@example.com','phone'=>'06301234567'])->assertCreated()->json();$this->patchJson('/api/clients/'.$c['id'].'/blacklist',['blocked'=>true,'reason'=>'Belső indok'])->assertOk();$this->postJson('/api/bookings',$this->booking(['clientId'=>$c['id']]))->assertCreated();$this->withSession(['admin'=>false]);$r=$this->postJson('/api/bookings',$this->booking(['name'=>'Más név','phone'=>'+36301234567','start'=>'2035-03-13T09:00:00Z']))->assertUnprocessable();$this->assertStringNotContainsString('Belső indok',$r->getContent());$this->getJson('/api/public')->assertJsonMissingPath('clients');$this->patchJson('/api/clients/'.$c['id'].'/blacklist',['blocked'=>false])->assertForbidden();$this->admin();$this->patchJson('/api/clients/'.$c['id'].'/blacklist?provider=2',['blocked'=>false])->assertForbidden();$this->patchJson('/api/clients/'.$c['id'].'/blacklist',['blocked'=>false])->assertOk();$this->withSession(['admin'=>false]);$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-13T09:00:00Z']))->assertCreated();}
 public function test_series_creation_and_cancellation_are_atomic_and_keep_individual_bookings():void{$this->admin();$r=$this->postJson('/api/bookings',$this->booking(['recurrence'=>['frequency'=>'weekly','count'=>4]]))->assertCreated()->assertJsonPath('seriesCount',4)->json();$s=app(SalonStore::class)->read();$this->assertCount(4,$s['bookings']);$this->assertCount(1,$s['clients']);$this->assertSame('2035-03-19T09:00:00.000000Z',$s['bookings'][1]['start']);$this->assertCount(1,array_unique(array_column($s['bookings'],'seriesId')));$this->postJson('/api/booking-series/'.$r['seriesId'].'/cancel')->assertOk()->assertJsonPath('cancelled',4);$this->assertSame(4,count(array_filter(app(SalonStore::class)->read()['bookings'],fn($b)=>$b['status']==='cancelled')));}
 public function test_series_conflict_rolls_back_clients_bookings_notifications_and_pass_reservations():void{$this->admin();$this->postJson('/api/bookings',$this->booking(['start'=>'2035-03-19T09:00:00Z']))->assertCreated();$jobs=DB::table('deliveries')->count();$this->postJson('/api/bookings',$this->booking(['recurrence'=>['frequency'=>'weekly','count'=>3]]))->assertUnprocessable();$this->assertCount(1,app(SalonStore::class)->read()['bookings']);$this->assertSame($jobs,DB::table('deliveries')->count());}
 public function test_public_cannot_create_series_and_monthly_dates_do_not_drift():void{$this->postJson('/api/bookings',$this->booking(['recurrence'=>['frequency'=>'weekly','count'=>3]]))->assertForbidden();$dates=\App\Services\RecurringBookings::starts('2035-01-31T09:00:00Z',['frequency'=>'monthly','count'=>3]);$this->assertSame('2035-02-28T09:00:00.000000Z',$dates[1]);$this->assertStringStartsWith('2035-03-31',$dates[2]);$this->assertCount(0,app(SalonStore::class)->read()['bookings']);}
 private function attended():array{$this->admin();$b=$this->postJson('/api/bookings',$this->booking())->assertCreated()->json();app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']=now()->subDays(2)->utc()->toISOString();$s['bookings'][0]['status']='confirmed';$s['bookings'][0]['attendance']='attended';});return $b;}
 public function test_review_request_is_once_and_secret_link_review_needs_attendance():void{$b=$this->attended();$this->postJson('/api/bookings/'.$b['id'].'/review-request')->assertOk()->assertJsonPath('queued',true);$this->postJson('/api/bookings/'.$b['id'].'/review-request')->assertOk()->assertJsonPath('queued',false);$this->withSession(['admin'=>false]);$this->postJson('/api/manage/review',['token'=>$b['token'],'score'=>5,'text'=>'Nagyszerű volt.'])->assertCreated();$this->postJson('/api/manage/review',['token'=>$b['token'],'score'=>4,'text'=>'Második'])->assertUnprocessable();$this->getJson('/api/public')->assertJsonPath('reviews.0.score',5);}
 public function test_automatic_reviews_do_not_retroactively_mail_history_or_no_shows():void{$b=$this->attended();$this->assertSame(0,ReviewRequests::run());$s=app(SalonStore::class)->read();$this->putJson('/api/config',['settings'=>array_replace($s['settings'],['reviewRequestsEnabled'=>true,'reviewRequestDelayHours'=>0])])->assertOk();$this->assertSame(0,ReviewRequests::run());app(SalonStore::class)->mutate(function(&$s){$s['settings']['reviewRequestsEnabledAt']=now()->subDays(3)->toISOString();});$this->assertSame(1,ReviewRequests::run());$this->assertSame(0,ReviewRequests::run());app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['attendance']='no_show';$s['bookings'][0]['status']='no_show';});$this->assertSame('skipped',ReviewRequests::deliver($b['id'],app(SalonStore::class)->read(),true));}
 public function test_recurring_nonexistent_spring_clock_time_is_rejected():void{$this->expectException(\InvalidArgumentException::class);\App\Services\RecurringBookings::starts('2035-03-24T02:30:00+01:00',['frequency'=>'daily','count'=>2]);}
 public function test_validation_uses_selected_language_and_forgot_does_not_reveal_accounts():void{$this->withHeader('X-App-Language','de')->postJson('/api/guest/auth/register',['email'=>'wrong'])->assertUnprocessable()->assertJsonPath('errors.email.0','Bitte gib eine gültige E-Mail-Adresse ein.');$this->postJson('/api/guest/auth/forgot',['email'=>'unknown@example.com'])->assertOk()->assertExactJson(['ok'=>true]);$this->assertSame(0,DB::table('deliveries')->count());}
}
